1	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
2	
3	const corsHeaders = {
4	  "Access-Control-Allow-Origin": "*",
5	  "Access-Control-Allow-Headers":
6	    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
7	};
8	
9	// ─── Helpers ───
10	
11	async function verifyAdmin(req: Request) {
12	  const authHeader = req.headers.get("Authorization");
13	  if (!authHeader?.startsWith("Bearer ")) throw new Error("Unauthorized");
14	
15	  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
16	  const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
17	  const supabaseUser = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, {
18	    global: { headers: { Authorization: authHeader } },
19	  });
20	
21	  const { data: userData, error: userError } = await supabaseUser.auth.getUser();
22	  if (userError || !userData?.user) throw new Error("Unauthorized");
23	
24	  const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);
25	  const { data: roleData } = await supabaseAdmin
26	    .from("user_roles")
27	    .select("role")
28	    .eq("user_id", userData.user.id)
29	    .eq("role", "admin")
30	    .maybeSingle();
31	
32	  if (!roleData) throw new Error("Forbidden");
33	  return supabaseAdmin;
34	}
35	
36	function getDodoConfig() {
37	  const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
38	  if (!DODO_API_KEY) throw new Error("DODO_PAYMENTS_API_KEY not configured");
39	  const env = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
40	  const baseUrl = env === "live_mode"
41	    ? "https://live.dodopayments.com"
42	    : "https://test.dodopayments.com";
43	  return { DODO_API_KEY, baseUrl };
44	}
45	
46	async function getBrandId(supabaseAdmin: any): Promise<string | null> {
47	  const { data } = await supabaseAdmin
48	    .from("platform_config")
49	    .select("dodo_brand_id")
50	    .limit(1)
51	    .single();
52	  return data?.dodo_brand_id || null;
53	}
54	
55	async function dodoFetch(baseUrl: string, apiKey: string, path: string, method: string, body?: any) {
56	  const opts: RequestInit = {
57	    method,
58	    headers: {
59	      "Content-Type": "application/json",
60	      Authorization: `Bearer ${apiKey}`,
61	    },
62	  };
63	  if (body) opts.body = JSON.stringify(body);
64	  const resp = await fetch(`${baseUrl}${path}`, opts);
65	  const text = await resp.text();
66	  return { ok: resp.ok, status: resp.status, text, json: () => { try { return JSON.parse(text); } catch { return null; } } };
67	}
68	
69	// ─── Credit Entitlement helpers ───
70	
71	async function createCreditEntitlement(baseUrl: string, apiKey: string, price: number, credits: number): Promise<string | null> {
72	  const name = `$${price} - ${credits} Credits`;
73	  console.log(`Creating Dodo credit entitlement: "${name}"...`);
74	  const resp = await dodoFetch(baseUrl, apiKey, "/credit-entitlements", "POST", {
75	    name,
76	    unit: "credits",
77	    precision: 0,
78	    rollover_enabled: false,
79	    overage_enabled: false,
80	    description: `${credits} credits included. 1 credit = 1 resume ranked.`,
81	  });
82	  if (!resp.ok) { console.error("Failed to create credit entitlement:", resp.status, resp.text); return null; }
83	  const ent = resp.json();
84	  console.log("Credit entitlement created:", ent?.id, name);
85	  return ent?.id || null;
86	}
87	
88	async function archiveCreditEntitlement(baseUrl: string, apiKey: string, id: string) {
89	  console.log("Archiving credit entitlement:", id);
90	  await dodoFetch(baseUrl, apiKey, `/credit-entitlements/${id}`, "PATCH", { is_active: false });
91	}
92	
93	async function restoreCreditEntitlement(baseUrl: string, apiKey: string, id: string) {
94	  console.log("Restoring credit entitlement:", id);
95	  await dodoFetch(baseUrl, apiKey, `/credit-entitlements/${id}`, "PATCH", { is_active: true });
96	}
97	
98	// ─── Main handler ───
99	
100	Deno.serve(async (req) => {
101	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
102	
103	  try {
104	    const supabaseAdmin = await verifyAdmin(req);
105	    const { DODO_API_KEY, baseUrl } = getDodoConfig();
106	    const body = await req.json();
107	    const { action, type, name, price, credits, billing_type, product_id, credit_entitlement_id, description, pay_what_you_want, pwyw_min_price, pwyw_max_price } = body;
108	
109	    const validActions = ["create", "update", "deactivate", "reactivate", "verify", "fetch_brands"];
110	    if (!action || !validActions.includes(action)) {
111	      return new Response(JSON.stringify({ error: `Invalid action. Use: ${validActions.join(", ")}` }), {
112	        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
113	      });
114	    }
115	
116	    let result: any = {};
117	
118	    // ─── FETCH BRANDS ───
119	    if (action === "fetch_brands") {
120	      const resp = await dodoFetch(baseUrl, DODO_API_KEY, "/brands", "GET");
121	      if (!resp.ok) {
122	        return new Response(JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: resp.text }), {
123	          status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" },
124	        });
125	      }
126	      result = { brands: resp.json() };
127	      return new Response(JSON.stringify({ success: true, ...result }), {
128	        headers: { ...corsHeaders, "Content-Type": "application/json" },
129	      });
130	    }
131	
132	    // ─── VERIFY ───
133	    if (action === "verify") {
134	      if (!product_id) {
135	        return new Response(JSON.stringify({ error: "product_id required for verify" }), {
136	          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
137	        });
138	      }
139	      const resp = await dodoFetch(baseUrl, DODO_API_KEY, `/products/${product_id}`, "GET");
140	      if (!resp.ok) {
141	        result = { exists: false, status: resp.status, error: resp.text };
142	      } else {
143	        const product = resp.json();
144	        result = {
145	          exists: true,
146	          is_active: product?.is_active ?? true,
147	          dodo_name: product?.name,
148	          dodo_price: product?.price,
149	          product,
150	        };
151	      }
152	      return new Response(JSON.stringify({ success: true, ...result }), {
153	        headers: { ...corsHeaders, "Content-Type": "application/json" },
154	      });
155	    }
156	
157	    // ─── CREATE ───
158	    if (action === "create") {
159	      const brandId = await getBrandId(supabaseAdmin);
160	
161	      const priceObj: any = {
162	        currency: "USD",
163	        discount: 0,
164	        purchasing_power_parity: false,
165	      };
166	
167	      if (type === "plan") {
168	        priceObj.type = "recurring_price";
169	        priceObj.payment_frequency_count = 1;
170	        priceObj.payment_frequency_interval = billing_type === "yearly" ? "Year" : "Month";
171	        priceObj.subscription_period_count = 1;
172	        priceObj.subscription_period_interval = billing_type === "yearly" ? "Year" : "Month";
173	        priceObj.trial_period_days = 0;
174	        priceObj.price = Math.round(price * 100);
175	      } else {
176	        priceObj.type = "one_time_price";
177	        priceObj.price = Math.round(price * 100);
178	        // PWYW support for wallet top-ups — flag MUST be inside the price object
179	        if (pay_what_you_want) {
180	          priceObj.pay_what_you_want = true;
181	          priceObj.pay_what_you_want_min_price = pwyw_min_price ? Math.round(pwyw_min_price * 100) : Math.round(price * 100);
182	          priceObj.pay_what_you_want_max_price = pwyw_max_price ? Math.round(pwyw_max_price * 100) : 100000;
183	        }
184	      }
185	
186	      const createPayload: any = {
187	        name,
188	        tax_category: "saas",
189	        price: priceObj,
190	      };
191	
192	      if (pay_what_you_want) createPayload.pay_what_you_want = true;
193	      if (description) createPayload.description = description;
194	      if (brandId) createPayload.brand_id = brandId;
195	
196	      // Attach credit entitlement
197	      let newCreditEntitlementId: string | null = null;
198	      if (credits && credits > 0) {
199	        newCreditEntitlementId = await createCreditEntitlement(baseUrl, DODO_API_KEY, price, credits);
200	        if (newCreditEntitlementId) {
201	          createPayload.credit_entitlements = [{ credit_entitlement_id: newCreditEntitlementId, credits_amount: String(credits) }];
202	        }
203	      }
204	
205	      console.log("Creating Dodo product:", JSON.stringify(createPayload));
206	      const resp = await dodoFetch(baseUrl, DODO_API_KEY, "/products", "POST", createPayload);
207	
208	      if (!resp.ok) {
209	        console.error("Dodo create failed:", resp.status, resp.text);
210	        return new Response(JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: resp.text }), {
211	          status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" },
212	        });
213	      }
214	
215	      result = resp.json();
216	      if (newCreditEntitlementId) result.credit_entitlement_id = newCreditEntitlementId;
217	      console.log("Dodo product created:", result?.product_id);
218	    }
219	
220	    // ─── UPDATE ───
221	    else if (action === "update") {
222	      if (!product_id) {
223	        return new Response(JSON.stringify({ error: "product_id required for update" }), {
224	          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
225	        });
226	      }
227	
228	      // Verify product exists on Dodo first
229	      const verifyResp = await dodoFetch(baseUrl, DODO_API_KEY, `/products/${product_id}`, "GET");
230	      if (!verifyResp.ok) {
231	        return new Response(JSON.stringify({
232	          error: "Product not found on Dodo",
233	          not_found: true,
234	          details: `Product ${product_id} does not exist or was deleted on Dodo. Please unlink and recreate it.`,
235	        }), { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } });
236	      }
237	
238	      const patchPayload: any = {};
239	      if (name) patchPayload.name = name;
240	      if (description !== undefined) patchPayload.description = description || "";
241	      if (pay_what_you_want !== undefined) patchPayload.pay_what_you_want = pay_what_you_want;
242	      if (price !== undefined && price !== null) {
243	        const priceObj: any = { currency: "USD", discount: 0, purchasing_power_parity: false };
244	        if (type === "plan") {
245	          priceObj.type = "recurring_price";
246	          priceObj.payment_frequency_count = 1;
247	          priceObj.payment_frequency_interval = billing_type === "yearly" ? "Year" : "Month";
248	          priceObj.subscription_period_count = 1;
249	          priceObj.subscription_period_interval = billing_type === "yearly" ? "Year" : "Month";
250	          priceObj.trial_period_days = 0;
251	          priceObj.price = Math.round(price * 100);
252	        } else {
253	          priceObj.type = "one_time_price";
254	          priceObj.price = Math.round(price * 100);
255	          if (pay_what_you_want) {
256	            priceObj.pay_what_you_want = true;
257	            priceObj.pay_what_you_want_min_price = pwyw_min_price ? Math.round(pwyw_min_price * 100) : Math.round(price * 100);
258	            priceObj.pay_what_you_want_max_price = pwyw_max_price ? Math.round(pwyw_max_price * 100) : 100000;
259	          }
260	        }
261	        patchPayload.price = priceObj;
262	      }
263	
264	      let newCreditEntitlementId: string | null = null;
265	      if (credits !== undefined && credits !== null && credits > 0) {
266	        newCreditEntitlementId = await createCreditEntitlement(baseUrl, DODO_API_KEY, price ?? 0, credits);
267	        if (newCreditEntitlementId) {
268	          patchPayload.credit_entitlements = [{ credit_entitlement_id: newCreditEntitlementId, credits_amount: String(credits) }];
269	        }
270	      }
271	
272	      console.log("Updating Dodo product:", product_id, JSON.stringify(patchPayload));
273	      const resp = await dodoFetch(baseUrl, DODO_API_KEY, `/products/${product_id}`, "PATCH", patchPayload);
274	
275	      if (!resp.ok) {
276	        console.error("Dodo update failed:", resp.status, resp.text);
277	        if (resp.status === 404) {
278	          return new Response(JSON.stringify({ error: "Product not found on Dodo", not_found: true, details: "Product was deleted on Dodo. Unlink and recreate." }), {
279	            status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
280	          });
281	        }
282	        return new Response(JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: resp.text }), {
283	          status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" },
284	        });
285	      }
286	
287	      result = { updated: true, product_id };
288	      if (newCreditEntitlementId) result.credit_entitlement_id = newCreditEntitlementId;
289	    }
290	
291	    // ─── DEACTIVATE ───
292	    else if (action === "deactivate") {
293	      if (!product_id) {
294	        return new Response(JSON.stringify({ success: true, skipped: true }), {
295	          headers: { ...corsHeaders, "Content-Type": "application/json" },
296	        });
297	      }
298	      console.log("Archiving Dodo product:", product_id);
299	      const resp = await dodoFetch(baseUrl, DODO_API_KEY, `/products/${product_id}`, "PATCH", { is_active: false });
300	      if (!resp.ok && resp.status === 404) {
301	        result = { deactivated: true, product_id, not_found: true, warning: "Product not found on Dodo — already deleted." };
302	      } else {
303	        if (credit_entitlement_id) await archiveCreditEntitlement(baseUrl, DODO_API_KEY, credit_entitlement_id);
304	        result = { deactivated: true, product_id };
305	      }
306	    }
307	
308	    // ─── REACTIVATE ───
309	    else if (action === "reactivate") {
310	      if (!product_id) {
311	        return new Response(JSON.stringify({ success: true, skipped: true }), {
312	          headers: { ...corsHeaders, "Content-Type": "application/json" },
313	        });
314	      }
315	      console.log("Reactivating Dodo product:", product_id);
316	      const resp = await dodoFetch(baseUrl, DODO_API_KEY, `/products/${product_id}`, "PATCH", { is_active: true });
317	      if (!resp.ok && resp.status === 404) {
318	        return new Response(JSON.stringify({ error: "Product not found on Dodo", not_found: true, details: "Product was deleted on Dodo. Unlink and recreate." }), {
319	          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
320	        });
321	      }
322	      if (credit_entitlement_id) await restoreCreditEntitlement(baseUrl, DODO_API_KEY, credit_entitlement_id);
323	      result = { reactivated: true, product_id };
324	    }
325	
326	    return new Response(JSON.stringify({ success: true, ...result }), {
327	      headers: { ...corsHeaders, "Content-Type": "application/json" },
328	    });
329	  } catch (err: unknown) {
330	    const msg = err instanceof Error ? err.message : String(err);
331	    const status = msg === "Unauthorized" ? 401 : msg === "Forbidden" ? 403 : 500;
332	    console.error("manage-dodo-product error:", err);
333	    return new Response(JSON.stringify({ error: msg }), {
334	      status, headers: { ...corsHeaders, "Content-Type": "application/json" },
335	    });
336	  }
337	});
