1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
3	
4	const corsHeaders = {
5	  "Access-Control-Allow-Origin": "*",
6	  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
7	};
8	
9	serve(async (req) => {
10	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
11	
12	  try {
13	    const body = await req.json();
14	    const {
15	      error_type,
16	      function_name,
17	      severity = "warning",
18	      error_message,
19	      error_stack,
20	      context_json,
21	      user_id,
22	    } = body;
23	
24	    if (!error_message) {
25	      return new Response(JSON.stringify({ ok: false, reason: "missing error_message" }), {
26	        headers: { ...corsHeaders, "Content-Type": "application/json" },
27	      });
28	    }
29	
30	    const supabase = createClient(
31	      Deno.env.get("SUPABASE_URL")!,
32	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
33	    );
34	
35	    // Dedup: skip if same error (same message + source) was logged in the last 5 minutes
36	    const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
37	    const { data: existing } = await supabase
38	      .from("system_error_logs")
39	      .select("id")
40	      .eq("error_message", String(error_message).slice(0, 500))
41	      .eq("function_name", function_name ?? "frontend")
42	      .gte("created_at", fiveMinAgo)
43	      .limit(1);
44	
45	    if (existing && existing.length > 0) {
46	      return new Response(JSON.stringify({ ok: true, deduped: true }), {
47	        headers: { ...corsHeaders, "Content-Type": "application/json" },
48	      });
49	    }
50	
51	    const safeMessage = String(error_message).replace(/<[^>]*>/g, "").slice(0, 2000);
52	    const safeStack = error_stack ? String(error_stack).replace(/<[^>]*>/g, "").slice(0, 5000) : null;
53	
54	    await supabase.from("system_error_logs").insert({
55	      function_name: (function_name ?? "frontend").slice(0, 100),
56	      error_type: (error_type ?? "ClientError").slice(0, 100),
57	      severity: ["critical", "warning", "info"].includes(severity) ? severity : "warning",
58	      error_message: safeMessage,
59	      error_stack: safeStack,
60	      context_json: context_json ?? {},
61	      user_id: user_id ?? null,
62	      is_resolved: false,
63	    });
64	
65	    return new Response(JSON.stringify({ ok: true }), {
66	      headers: { ...corsHeaders, "Content-Type": "application/json" },
67	    });
68	  } catch (err) {
69	    return new Response(JSON.stringify({ ok: false }), {
70	      status: 500,
71	      headers: { ...corsHeaders, "Content-Type": "application/json" },
72	    });
73	  }
74	});
